    async def layout_split(self, direction: Direction, *, content: TileContent | None = None, tile: TileId | None = None) -> Reply:
        """`layout.split`. Splits a tile and opens a new one beside it, which takes focus.

        content: The new tile; defaults to a terminal.
        direction: Which side of `tile` the new tile goes.
        tile: The tile to split; defaults to the focused one.
        """
        return await self._call("layout.split", {"content": content, "direction": direction, "tile": tile})

    async def layout_focus(self, direction: Direction) -> Reply:
        """`layout.focus`. Moves focus to the neighbouring tile."""
        return await self._call("layout.focus", {"direction": direction})

    async def layout_swap(self, *, direction: Direction | None = None, tile: TileId | None = None, with_: TileId | None = None) -> Reply:
        """`layout.swap`. Swaps a tile with its neighbour in `direction`, or with tile `with`.

        direction: Swap with the neighbour this way. Give exactly one of `direction`, `with`.
        with_: Swap with this tile, which must be in the same tab.
        """
        return await self._call("layout.swap", {"direction": direction, "tile": tile, "with": with_})

    async def layout_move(self, direction: Direction, *, tile: TileId | None = None) -> Reply:
        """`layout.move`. Moves a tile one step: into its neighbour's slot, or to the tab's edge."""
        return await self._call("layout.move", {"direction": direction, "tile": tile})

    async def layout_resize(self, direction: Direction, *, amount: float | None = None, tile: TileId | None = None) -> Reply:
        """`layout.resize`. Moves a tile's edge in `direction` by `amount` (negative shrinks).

        amount: Share of the enclosing split to move the edge by. Defaults to 0.05.
        """
        return await self._call("layout.resize", {"amount": amount, "direction": direction, "tile": tile})

    async def layout_zoom(self, *, tile: TileId | None = None, zoomed: bool | None = None) -> Reply:
        """`layout.zoom`. Zooms a tile to fill its tab; leave `zoomed` out to toggle.

        zoomed: `true` zooms, `false` unzooms, absent toggles.
        """
        return await self._call("layout.zoom", {"tile": tile, "zoomed": zoomed})

    async def layout_split_auto(self, *, content: TileContent | None = None, tab: TabId | None = None) -> Reply:
        """`layout.split_auto`. Opens a tile at the end of the tab's stack, whichever tile has focus; a
        lone tile becomes master | stack. In a manual tab the stack is evened
        out afterwards; in a dynamic tab the tile goes where `[layout] insert`
        says.

        content: The new tile; defaults to a terminal.
        tab: Defaults to the focused tab.
        """
        return await self._call("layout.split_auto", {"content": content, "tab": tab})

    async def layout_promote(self, *, tile: TileId | None = None) -> Reply:
        """`layout.promote`. Swaps a tile with its tab's master (manual tab) or moves it to the
        front of the order (dynamic tab); focus stays on the tile.

        tile: Defaults to the focused tile.
        """
        return await self._call("layout.promote", {"tile": tile})

    async def layout_rotate(self, *, part: bool | None = None, reverse: bool | None = None, tab: TabId | None = None) -> Reply:
        """`layout.rotate`. Toggles master on the left ↔ master on top, keeping the stack's order.
        In a Tile tab, `reverse` makes it a quarter turn (absent: toggle;
        `false`: clockwise; `true`: anticlockwise) and `part` instead turns
        only the master area ("rotate part").

        part: Tile tabs: turn only the master area, so several masters sit side by side instead of stacked.
        reverse: Tile tabs: a quarter turn, anticlockwise when `true`. Absent toggles master left ↔ top.
        tab: Defaults to the focused tab.
        """
        return await self._call("layout.rotate", {"part": part, "reverse": reverse, "tab": tab})

    async def layout_equalize(self, *, tab: TabId | None = None) -> Reply:
        """`layout.equalize`. Gives every tile in the tab's stack the same size.

        tab: Defaults to the focused tab.
        """
        return await self._call("layout.equalize", {"tab": tab})

    async def layout_set(self, kind: LayoutKind, *, tab: TabId | None = None) -> Reply:
        """`layout.set`. Switches a tab to a layout kind: `manual` or a dynamic one.

        tab: Defaults to the focused tab.
        """
        return await self._call("layout.set", {"kind": kind, "tab": tab})

    async def layout_toggle(self, kind: LayoutKind, *, tab: TabId | None = None) -> Reply:
        """`layout.toggle`. Switches a tab to `kind`, or back to its previous kind if `kind` is
        already active.

        tab: Defaults to the focused tab.
        """
        return await self._call("layout.toggle", {"kind": kind, "tab": tab})

    async def layout_cycle(self, *, step: int | None = None, tab: TabId | None = None) -> Reply:
        """`layout.cycle`. Steps through the configured cycle of layout kinds.

        step: Positions to move through the cycle; negative goes back. Defaults to 1.
        tab: Defaults to the focused tab.
        """
        return await self._call("layout.cycle", {"step": step, "tab": tab})

    async def layout_masters(self, *, delta: int | None = None, tab: TabId | None = None) -> Reply:
        """`layout.masters`. Adds (or with a negative `delta` removes) masters in a Tile or Three
        Column tab.

        delta: How many masters to add; negative removes. Defaults to 1.
        tab: Defaults to the focused tab.
        """
        return await self._call("layout.masters", {"delta": delta, "tab": tab})

    async def layout_master_ratio(self, *, delta: float | None = None, tab: TabId | None = None) -> Reply:
        """`layout.master_ratio`. Grows (positive `delta`) or shrinks the master area of a Tile or Three
        Column tab.

        delta: Change in the master area's share; negative shrinks. Defaults to 0.05.
        tab: Defaults to the focused tab.
        """
        return await self._call("layout.master_ratio", {"delta": delta, "tab": tab})

    async def layout_move_order(self, *, step: int | None = None, tile: TileId | None = None) -> Reply:
        """`layout.move_order`. Moves a tile `step` places along its dynamic tab's order, wrapping.

        step: Places to move; negative moves towards the front. Defaults to 1.
        tile: Defaults to the focused tile.
        """
        return await self._call("layout.move_order", {"step": step, "tile": tile})

    async def terminal_bind(self, herdr: HerdrRef, tile: TileId) -> Reply:
        """`terminal.bind`. Records the herdr pane a terminal tile views. Sent by the herdr adapter."""
        return await self._call("terminal.bind", {"herdr": herdr, "tile": tile})

    async def terminal_respawn(self, *, tile: TileId | None = None) -> Reply:
        """`terminal.respawn`. Gives an ended terminal tile a fresh herdr pane, keeping the tile's id
        and place. The new pane gets its own herdr tab and the tile's cwd.

        tile: Defaults to the focused tile.
        """
        return await self._call("terminal.respawn", {"tile": tile})

    async def terminal_send_text(self, text: str, *, tile: TileId | None = None) -> Reply:
        """`terminal.send_text`.

        text: Sent literally, as if pasted.
        """
        return await self._call("terminal.send_text", {"text": text, "tile": tile})

    async def terminal_send_keys(self, keys: list[str], *, tile: TileId | None = None) -> Reply:
        """`terminal.send_keys`.

        keys: Key names in herdr's notation, e.g. `enter`, `ctrl+c`, `up`.
        """
        return await self._call("terminal.send_keys", {"keys": keys, "tile": tile})

    async def terminal_read(self, *, lines: int | None = None, source: ReadSource | None = None, tile: TileId | None = None) -> Reply:
        """`terminal.read`. Reads a terminal's screen or history; replies `text`. History lives in
        herdr, not in the tile (ADR 0005).

        lines: Upper bound on lines returned.
        """
        return await self._call("terminal.read", {"lines": lines, "source": source, "tile": tile})

    async def terminal_scroll(self, offset_from_bottom: int, *, tile: TileId | None = None) -> Reply:
        """`terminal.scroll`. Scrolls a terminal's view; replies `scroll`. 0 is the live bottom.

        offset_from_bottom: Lines above the live bottom; 0 returns to it.
        """
        return await self._call("terminal.scroll", {"offset_from_bottom": offset_from_bottom, "tile": tile})

    async def terminal_search(self, query: str, *, case_sensitive: bool | None = None, lines: int | None = None, locate: bool | None = None, tile: TileId | None = None) -> Reply:
        """`terminal.search`. Finds lines containing `query` in a terminal's history; replies
        `matches`. Runs over `recent_unwrapped` output in the core.

        lines: How many lines of history to search; herdr's default when absent, or all of it with `locate`.
        locate: Also work out where each match sits in herdr's buffer (`row`) and the `terminal.scroll` offset that shows it mid-view, as a find bar needs. Costs two more herdr calls.
        query: Literal text to find.
        """
        return await self._call("terminal.search", {"case_sensitive": case_sensitive, "lines": lines, "locate": locate, "query": query, "tile": tile})

    async def events_subscribe(self, *, filter: list[str] | None = None, tile: TileId | None = None, workspace: WorkspaceId | None = None) -> Reply:
        """`events.subscribe`. Streams events on this connection as `events.event` notifications;
        replies `subscribed`. Answered by the API server, not the engine.

        filter: Event names or prefixes. `tile.created` matches that event only; `tile.`, `tile.*` and `tile` match every `tile.…` event. Empty or absent means every event.
        tile: Only events about this tile: its own `tile.*`, `preview.updated` and `agent.state_changed` events, layout changes of its tab, and focus changes to or from it.
        workspace: Only events about this workspace: its own events, its tabs' and its tiles', and `focus.changed` when focus lands in it. Events about no particular workspace (`herdr.status`, window events) are left out.
        """
        return await self._call("events.subscribe", {"filter": filter, "tile": tile, "workspace": workspace})

    async def events_unsubscribe(self, subscription: int) -> Reply:
        """`events.unsubscribe`. Ends a subscription made on this connection.

        subscription: The `subscription` from `events.subscribe`'s reply.
        """
        return await self._call("events.unsubscribe", {"subscription": subscription})

    async def layout_apply(self, *, base_dir: str | None = None, mode: ApplyMode | None = None, path: str | None = None, toml: str | None = None, workspace: WorkspaceId | None = None) -> Reply:
        """`layout.apply`. Opens a project layout file's tabs and tiles; replies `created` with
        the workspace and first tab.

        base_dir: What relative `cwd` and `path` values in the file resolve against. Defaults to the file's directory, or the workspace's cwd for `toml`.
        path: A layout file (`.azulejo.toml`). Give exactly one of `path` and `toml`.
        toml: The layout file's text.
        workspace: For `new_tab` and `replace_tab`; the focused workspace by default.
        """
        return await self._call("layout.apply", {"base_dir": base_dir, "mode": mode, "path": path, "toml": toml, "workspace": workspace})

    async def layout_export(self, *, path: str | None = None, tab: TabId | None = None, workspace: WorkspaceId | None = None) -> Reply:
        """`layout.export`. A tab or workspace as layout-file TOML; replies `layout_file`.

        path: Also write the file here. Paths in it are made relative to its directory where they're inside it.
        tab: Export one tab. Without it, the whole workspace.
        workspace: The workspace to export; the focused one by default.
        """
        return await self._call("layout.export", {"path": path, "tab": tab, "workspace": workspace})

    async def commands_list(self) -> Reply:
        """`commands.list`. Every action the palette offers, with its current key chords;
        replies `commands`.
        """
        return await self._call("commands.list", {})

    async def machines_list(self) -> Reply:
        """`machines.list`. Local plus herdr's saved machines and their connection state;
        replies `machines`.
        """
        return await self._call("machines.list", {})
